use js_runtime::{Runtime,Value,EnvId,JsResult};
use js_runtime::property_slots::LiteralReadSite;
static METHOD:LiteralReadSite=LiteralReadSite::new("method");
fn put(rt:&mut Runtime,target:Value,value:Value){let key=rt.intern("method");rt.define_data(target,key,value,true,true,true).unwrap();}
fn read(rt:&mut Runtime,target:Value)->Value{rt.get_literal_cached(target,&METHOD).unwrap()}
fn getter(rt:&mut Runtime,this:Value,_:&[Value],_:EnvId)->JsResult<Value>{let key=rt.intern("tag");rt.get(this,key)}
#[test]fn ten_receivers_share_prototype_cache_and_read_fresh_bits(){let mut rt=Runtime::new();rt.enable_trusted_generated_property_caches();let proto=rt.object();put(&mut rt,proto,Value::Number(-0.0));let receivers=(0..10).map(|_|{let x=rt.object();rt.set_prototype(x,proto).unwrap();x}).collect::<Vec<_>>();for round in 0..30{let bits=if round%2==0{0x8000000000000000}else{0x7ff0000000000042+round};put(&mut rt,proto,Value::Number(f64::from_bits(bits)));for &x in &receivers{let Value::Number(n)=read(&mut rt,x)else{panic!()};assert_eq!(n.to_bits(),bits);}}}
#[test]fn own_and_intermediate_shadow_delete_reinsert_and_prototype_changes(){let mut rt=Runtime::new();rt.enable_trusted_generated_property_caches();let owner=rt.object();put(&mut rt,owner,Value::Number(1.0));let middle=rt.object();rt.set_prototype(middle,owner).unwrap();let x=rt.object();rt.set_prototype(x,middle).unwrap();for _ in 0..3{assert_eq!(read(&mut rt,x),Value::Number(1.0));}put(&mut rt,middle,Value::Number(2.0));assert_eq!(read(&mut rt,x),Value::Number(2.0));put(&mut rt,x,Value::Number(3.0));assert_eq!(read(&mut rt,x),Value::Number(3.0));let key=rt.intern("method");rt.delete(x,key,true).unwrap();rt.delete(middle,key,true).unwrap();assert_eq!(read(&mut rt,x),Value::Number(1.0));let other=rt.object();put(&mut rt,other,Value::Number(4.0));rt.set_prototype(middle,other).unwrap();assert_eq!(read(&mut rt,x),Value::Number(4.0));rt.delete(other,key,true).unwrap();put(&mut rt,other,Value::Number(5.0));assert_eq!(read(&mut rt,x),Value::Number(5.0));}
#[test]fn data_to_accessor_always_calls_with_original_receiver(){let mut rt=Runtime::new();rt.enable_trusted_generated_property_caches();let owner=rt.object();put(&mut rt,owner,Value::Number(1.0));let x=rt.object();rt.set_prototype(x,owner).unwrap();assert_eq!(read(&mut rt,x),Value::Number(1.0));let tag=rt.intern("tag");rt.define_data(x,tag,Value::Number(91.0),true,true,true).unwrap();let g=rt.native_function("getter",0,getter).unwrap();let key=rt.intern("method");rt.define_accessor(owner,key,Some(g),None,true,true).unwrap();assert_eq!(read(&mut rt,x),Value::Number(91.0));assert_eq!(read(&mut rt,x),Value::Number(91.0));}
#[test]fn arrays_and_functions_keep_generic_semantics(){let mut rt=Runtime::new();rt.enable_trusted_generated_property_caches();let owner=rt.object();put(&mut rt,owner,Value::Number(1.0));let x=rt.object();rt.set_prototype(x,owner).unwrap();assert_eq!(read(&mut rt,x),Value::Number(1.0));let array=rt.array(&[]);rt.set_prototype(array,owner).unwrap();assert_eq!(read(&mut rt,array),Value::Number(1.0));let key=rt.intern("method");rt.define_data(array,key,Value::Number(2.0),true,true,true).unwrap();assert_eq!(read(&mut rt,array),Value::Number(2.0));rt.set_prototype(x,array).unwrap();assert_eq!(read(&mut rt,x),Value::Number(2.0));}
#[test]fn bloom_has_no_false_negatives_after_many_inserts_deletes_and_reinsertions(){let mut rt=Runtime::new();rt.enable_trusted_generated_property_caches();let object=rt.object();for i in 0..4096{let key=rt.intern(&format!("key{i}"));rt.define_data(object,key,Value::Number(i as f64),true,true,true).unwrap();}for i in 0..4096{let key=rt.intern(&format!("key{i}"));assert_eq!(rt.get(object,key).unwrap(),Value::Number(i as f64));if i%2==0{rt.delete(object,key,true).unwrap();}}for i in (0..4096).step_by(2){let key=rt.intern(&format!("key{i}"));rt.define_data(object,key,Value::Number(-(i as f64)),true,true,true).unwrap();assert_eq!(rt.get(object,key).unwrap(),Value::Number(-(i as f64)));}}

#[test]fn public_raw_writes_remain_valid_by_default_and_after_explicit_disable(){let mut rt=Runtime::new();let x=rt.object();let id=rt.object_id(x).unwrap();let key=js_runtime::PropertyKey(rt.intern("raw"));rt.objects[id.0].property_index.insert(key,0);rt.objects[id.0].properties.push(Some((key,js_runtime::Descriptor::data(Value::Number(7.0),true,true,true))));assert_eq!(rt.get(x,key).unwrap(),Value::Number(7.0));rt.enable_trusted_generated_property_caches();assert_eq!(rt.get(x,key).unwrap(),Value::Number(7.0));rt.disable_trusted_generated_property_caches();let next=js_runtime::PropertyKey(rt.intern("after"));rt.objects[id.0].property_index.insert(next,1);rt.objects[id.0].properties.push(Some((next,js_runtime::Descriptor::data(Value::Number(8.0),true,true,true))));assert_eq!(rt.get(x,next).unwrap(),Value::Number(8.0));}
fn gc_rounds(rt:&mut Runtime,_:Value,_:&[Value],parent:EnvId)->JsResult<Value>{let env=rt.child_env(parent);for(name,n)in[("battles",23.0),("warmup",0.0),("battleIndex",0.0)]{rt.declare(env,name,Value::Number(n))?;}let initial=rt.objects.len();let mut seen=std::collections::HashSet::new();let mut reused=false;for round in 0..23{let owner=rt.object();let oid=rt.object_id(owner)?;reused|=!seen.insert(oid);put(rt,owner,Value::Number(round as f64));let middle=rt.object();rt.set_prototype(middle,owner)?;let receiver=rt.object();rt.set_prototype(receiver,middle)?;for _ in 0..3{assert_eq!(read(rt,receiver),Value::Number(round as f64));}rt.assign(env,"battleIndex",Value::Number(round as f64),false)?;rt.collect_native_battle_backedge(env,parent)?;}assert!(reused);assert!(rt.objects.len()<initial+16);Ok(Value::Number(rt.native_battle_gc_stats().collections as f64))}
#[test]fn weak_cache_locations_survive_twenty_three_id_reuse_rounds_without_retaining_objects(){let mut rt=Runtime::new();rt.enable_trusted_generated_property_caches();let function=rt.make_closure(gc_rounds,rt.global_env,0,"__nativeRun");rt.set_function_source(function,&include_str!("../src/native_battle_run.js").encode_utf16().collect::<Vec<_>>()).unwrap();rt.enable_native_battle_gc();assert_eq!(rt.call(function,Value::Undefined,&[]).unwrap(),Value::Number(23.0));}
